// Idempotent create using an idempotency key
async function createPayment(req) {
  const key = req.headers['idempotency-key'];
  const existing = await store.get(key);
  if (existing) return existing;             // replay -> same result
  const result = await charge(req.body);     // do the side effect once
  await store.set(key, result, { ttl: '24h' });
  return result;
}
